begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','34000000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('34000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','share-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,7) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Private shared project','UTC','GBP','2026-01-01',null,'team_project') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Private Category' from ctx returning id) select * from c;
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Private shared activity","kind":"other","activity_type":"task","notes":"Private notes"}',null)).id;
create temp table sibling as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Sibling activity","kind":"other","activity_type":"task"}',null)).id;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('34000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Share role fixture',case when i=3 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,3) i;
insert into storage.objects(bucket_id,name) select 'project-media',id::text||'/private-share.png' from ctx;
insert into storage.objects(bucket_id,name) select 'attachments',id::text||'/private-share.txt' from ctx;
select pg_temp.login(6);
create temp table other as select public.create_project('Other private project','UTC','GBP','2026-01-01') id;
create temp table other_cat as with c as(insert into public.project_areas(project_id,title) select id,'Other Category' from other returning id) select * from c;
create temp table other_activity as select (public.create_activity_in_category((select id from other),(select id from other_cat),'{"title":"Other activity","kind":"other","activity_type":"task"}',null)).id;
select pg_temp.login(1);
create temp table initial_activity as select to_jsonb(c) row from public.commitments c where id=(select id from activity);
create temp table initial_members as select jsonb_agg(to_jsonb(m) order by id) rows from public.project_members m where project_id=(select id from ctx);
create temp table tokens as select public.create_resource_share_link('activity',(select id from activity)) a;
select ok((select a ~ '^[0-9a-f]{64}$' from tokens),'256-bit token shape');
select is(public.create_resource_share_link('activity',(select id from activity)),(select a from tokens),'Create retry recovers same link');
select is(public.get_resource_share_link('activity',(select id from activity))->>'token',(select a from tokens),'Organizer recovers current token');
select is(public.resolve_shared_resource((select a from tokens)),jsonb_build_object('state','authorized','resource_type','activity','resource_id',(select id from activity),'project_id',(select id from ctx)),'Resolver returns only authorized route identifiers');
select throws_ok($$select public.create_resource_share_link('decision',(select id from activity))$$,'42501',null,'Activity ID is not a Decision');
select throws_ok($$select public.create_resource_share_link('file',(select id from activity))$$,'42501',null,'Files are not implicitly shareable');
select throws_ok($$select public.create_resource_share_link('activity; select * from public.users',(select id from activity))$$,'42501',null,'Resource type is never dynamic SQL');
select throws_ok($$select public.create_resource_share_link('activity',(select id from other_activity))$$,'42501',null,'Organizer cannot create foreign Activity link');
set local role postgres;
select is((select count(*)::int from app.resource_share_policies where resource_type='activity'),1,'One explicit Activity policy');
select is((select count(*)::int from app.resource_share_links where resource_id=(select id from activity) and revoked_at is null),1,'One current link after create retry');
select is((select token_hash from app.resource_share_links where resource_id=(select id from activity)),encode(extensions.digest((select a from tokens),'sha256'),'hex'),'SHA256 lookup');
select ok((select token_ciphertext is not null and to_jsonb(l)::text not like '%'||(select a from tokens)||'%' from app.resource_share_links l where resource_id=(select id from activity)),'No raw token in persisted link row');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('app.resource_share_links'::regclass,'app.resource_share_policies'::regclass)),'Private tables FORCE RLS');
select ok(not has_table_privilege('anon','app.resource_share_links','SELECT') and not has_table_privilege('authenticated','app.resource_share_links','SELECT') and not has_table_privilege('service_role','app.resource_share_links','SELECT'),'No client or service role direct token access');
select ok(not has_table_privilege('anon','vault.decrypted_secrets','SELECT') and not has_table_privilege('authenticated','vault.decrypted_secrets','SELECT'),'Clients cannot read Vault keys');
create temp table surfaces as select table_name from information_schema.columns where table_schema='public' and column_name='project_id';
grant select on ctx,activity,sibling,tokens,other_activity,surfaces to anon,authenticated;
create function pg_temp.isolated() returns boolean language plpgsql as $$ declare r record;n bigint;begin
 for r in select * from surfaces loop
  begin execute format('select count(*) from public.%I where project_id=$1',r.table_name) into n using (select id from ctx);
  exception when insufficient_privilege then n:=0; end;
  if n<>0 then raise exception 'Unexpected visibility in %',r.table_name; end if;
 end loop;
 return true;
end $$;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"sign_in"}'::jsonb,'Anonymous receives no resource type/project metadata');
select is(public.resolve_shared_resource('bad'),'{"state":"unavailable"}'::jsonb,'Malformed token unavailable');
select is(public.resolve_shared_resource(repeat('f',64)),'{"state":"unavailable"}'::jsonb,'Unknown token unavailable');
select is(public.resolve_shared_resource(null),'{"state":"unavailable"}'::jsonb,'Null token unavailable');
select throws_ok($$select * from public.commitments where id=(select id from activity)$$,'42501',null,'Anonymous cannot read Activity');
select throws_ok($$select public.get_resource_share_link('activity',(select id from activity))$$,'42501',null,'Anonymous cannot recover token');
select throws_ok($$select public.create_resource_share_link('activity',(select id from activity))$$,'42501',null,'Anonymous cannot create token');
select pg_temp.login(4);
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"unavailable"}'::jsonb,'Nonmember receives no metadata');
select is(public.resolve_shared_resource(repeat('f',64)),public.resolve_shared_resource((select a from tokens)),'Unauthorized and nonexistent indistinguishable');
select ok(pg_temp.isolated(),'Nonmember share holder sees no Categories/Activities/Budget/People/notes/timeline/health/notifications');
select is((select count(*)::int from public.projects where id=(select id from ctx)),0,'No project visibility');
select is((select count(*)::int from public.v_my_projects where project_id=(select id from ctx)),0,'No project list exposure');
select is((select count(*)::int from storage.objects where name like (select id::text||'/%' from ctx)),0,'No project storage exposure');
select throws_ok($$select * from public.get_project_health((select id from ctx))$$,'42501',null,'No health RPC bypass');
select is((select count(*)::int from public.get_project_timeline_events((select id from ctx),'2026-01-01','2027-01-01')),0,'No timeline RPC bypass');
select throws_ok($$select public.get_resource_share_link('activity',(select id from activity))$$,'42501',null,'Nonmember cannot recover');
select throws_ok($$select public.regenerate_resource_share_link('activity',(select id from activity))$$,'42501',null,'Nonmember cannot rotate');
select throws_ok($$select public.disable_resource_share_link('activity',(select id from activity))$$,'42501',null,'Nonmember cannot disable');
select throws_ok($$select * from app.resource_share_links$$,'42501',null,'Private rows inaccessible');
select throws_ok($$update app.resource_share_links set resource_id=(select id from sibling)$$,'42501',null,'Cannot substitute target');
select throws_ok($$insert into app.resource_share_policies values('decision','member_only','activity_member_v1',true,true)$$,'42501',null,'Cannot enable a policy');
select throws_ok($$select app.share_resource_policy('activity',(select id from activity))$$,'42501',null,'Internal policy inaccessible');
select throws_ok($$select app.bearer_token_decrypt(null,'resource_share')$$,'42501',null,'Internal crypto inaccessible');
select ok(not app.is_member((select id from ctx)),'Share possession creates no membership');
select pg_temp.login(1);
create temp table join_token as select public.regenerate_project_join_link((select id from ctx)) t;
select pg_temp.login(5);
select public.request_project_access((select t from join_token));
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"unavailable"}'::jsonb,'Pending join requester cannot resolve Activity');
select ok(pg_temp.isolated(),'Pending join requester retains zero project data');
select ok(not app.is_member((select id from ctx)),'Pending request plus share creates no membership');
select pg_temp.login(2);
select is(public.resolve_shared_resource((select a from tokens))->>'resource_id',(select id::text from activity),'Member resolves correct Activity');
select is((select count(*)::int from public.commitments where id=(select id from activity)),1,'Normal Activity read works independently of sharing');
select is(public.get_resource_share_link('activity',(select id from activity))->>'token',(select a from tokens),'Member may recover link');
select is(public.create_resource_share_link('activity',(select id from activity)),(select a from tokens),'Member may create idempotently');
select throws_ok($$select public.get_resource_share_link('activity',(select id from other_activity))$$,'42501',null,'Member cannot manage unreadable foreign resource');
select pg_temp.login(3);
select is(public.resolve_shared_resource((select a from tokens))->>'resource_id',(select id::text from activity),'Viewer uses normal read authorization');
select is((select count(*)::int from public.commitments where id=(select id from activity)),1,'Viewer normal read works');
select throws_ok($$select public.get_resource_share_link('activity',(select id from activity))$$,'42501',null,'Viewer recovery denied');
select throws_ok($$select public.create_resource_share_link('activity',(select id from activity))$$,'42501',null,'Viewer create denied');
select throws_ok($$select public.regenerate_resource_share_link('activity',(select id from activity))$$,'42501',null,'Viewer regeneration denied');
select throws_ok($$select public.disable_resource_share_link('activity',(select id from activity))$$,'42501',null,'Viewer disable denied');
with changed as(update public.commitments set notes='Viewer spoof' where id=(select id from activity) returning id) select is((select count(*)::int from changed),0,'Share grants Viewer no extra update rights');
select pg_temp.login(6);
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"unavailable"}'::jsonb,'Other project organizer cannot resolve');
select throws_ok($$select public.get_resource_share_link('activity',(select id from activity))$$,'42501',null,'Other project organizer cannot recover');
select throws_ok($$select public.create_resource_share_link('activity',(select id from activity))$$,'42501',null,'Other project organizer cannot create');
select throws_ok($$select public.regenerate_resource_share_link('activity',(select id from activity))$$,'42501',null,'Other project organizer cannot regenerate');
select throws_ok($$select public.disable_resource_share_link('activity',(select id from activity))$$,'42501',null,'Other project organizer cannot disable');
select pg_temp.login(1);
select is(public.get_resource_share_link('activity',(select id from activity))->>'token',(select a from tokens),'Fresh auth claims recover unchanged current token');
create temp table sibling_token as select public.create_resource_share_link('activity',(select id from sibling)) t;
alter table tokens add column b text;
select pg_temp.login(2);
update tokens set b=public.regenerate_resource_share_link('activity',(select id from activity));
select isnt((select a from tokens),(select b from tokens),'Member regeneration creates new random token');
select is(public.resolve_shared_resource((select a from tokens)),'{"state":"unavailable"}'::jsonb,'Old token invalid');
select is(public.resolve_shared_resource((select b from tokens))->>'resource_id',(select id::text from activity),'New token bound to same resource');
select is(public.get_resource_share_link('activity',(select id from activity))->>'token',(select b from tokens),'Regenerated link recoverable');
select public.disable_resource_share_link('activity',(select id from activity));
select is(public.resolve_shared_resource((select b from tokens)),'{"state":"unavailable"}'::jsonb,'Member disable invalidates');
select is(public.get_resource_share_link('activity',(select id from activity)),'{"active":false,"token":null}'::jsonb,'Disabled recovery has no credential');
select is(public.resolve_shared_resource((select t from sibling_token))->>'resource_id',(select id::text from sibling),'Other share link unaffected');
select is((select to_jsonb(c) from public.commitments c where id=(select id from activity)),(select row from initial_activity),'Lifecycle does not mutate Activity');
select is((select jsonb_agg(to_jsonb(m) order by id) from public.project_members m where project_id=(select id from ctx)),(select rows from initial_members),'Lifecycle does not mutate membership');
select pg_temp.login(1);
update tokens set b=public.regenerate_resource_share_link('activity',(select id from activity));
set local role postgres;
select is((select count(*)::int from app.resource_share_links where resource_id=(select id from activity) and revoked_at is null),1,'One current link after lifecycle');
select is((select count(*)::int from app.resource_share_links where resource_id=(select id from activity) and revoked_at is not null and token_ciphertext is not null),0,'Revocation clears retired ciphertext');
select ok(not exists(select 1 from public.audit_log where project_id=(select id from ctx) and entity_type='resource_share_links' and (coalesce(before::text,'')||coalesce(after::text,'')) ~ 'token_hash|token_ciphertext'),'Audit snapshots strip credentials');
select ok(not exists(select 1 from public.audit_log where project_id=(select id from ctx) and (coalesce(before::text,'')||coalesce(after::text,'')) like '%'||(select b from tokens)||'%'),'Audit contains no raw token');
select ok(not exists(select 1 from app.domain_events where project_id=(select id from ctx) and payload::text like '%'||(select b from tokens)||'%'),'Events contain no token');
select is((select count(*)::int from app.domain_events where project_id=(select id from ctx) and event_type like 'share%'),0,'No speculative share events');
select is((select count(*)::int from public.notifications where project_id=(select id from ctx) and kind not in ('activity_created','project_join_requested')),0,'No share notifications');
-- Defensive binding check even if privileged maintenance corrupts a target/project pair.
update app.resource_share_links set project_id=(select id from other) where token_hash=app.bearer_token_hash((select b from tokens));
select pg_temp.login(1);
select is(public.resolve_shared_resource((select b from tokens)),'{"state":"unavailable"}'::jsonb,'Mismatched resource/project cannot resolve');
set local role postgres;
update app.resource_share_links set project_id=(select id from ctx),created_at=now()-interval '2 days',expires_at=now()-interval '1 day' where token_hash=app.bearer_token_hash((select b from tokens));
select pg_temp.login(1);
select is(public.resolve_shared_resource((select b from tokens)),'{"state":"unavailable"}'::jsonb,'Expiry enforced server-side');
select is(public.get_resource_share_link('activity',(select id from activity))->>'active','false','Expired token not copyable');
update tokens set b=public.create_resource_share_link('activity',(select id from activity));
select is(public.resolve_shared_resource((select b from tokens))->>'state','authorized','Create replaces expired link safely');
update public.projects set status='archived' where id=(select id from ctx);
select is(public.resolve_shared_resource((select b from tokens))->>'state','authorized','Archived project retains existing reads');
select is(public.get_resource_share_link('activity',(select id from activity))->>'token',(select b from tokens),'Archived current link recoverable');
select throws_ok($$select public.create_resource_share_link('activity',(select id from activity))$$,'42501',null,'Archived creation denied');
select throws_ok($$select public.regenerate_resource_share_link('activity',(select id from activity))$$,'42501',null,'Archived regeneration denied');
select throws_ok($$select public.disable_resource_share_link('activity',(select id from activity))$$,'42501',null,'Archived mutation denied');
update public.projects set status='active' where id=(select id from ctx);
set local role postgres;
update public.project_members set status='removed',removed_at=now() where project_id=(select id from ctx) and user_id='34000000-0000-4000-8000-000000000002';
select pg_temp.login(2);
select is(public.resolve_shared_resource((select b from tokens)),'{"state":"unavailable"}'::jsonb,'Removal revokes share access immediately');
select throws_ok($$select public.get_resource_share_link('activity',(select id from activity))$$,'42501',null,'Former manager cannot recover token');
select pg_temp.login(1);
select public.soft_delete_commitment((select id from activity));
select is(public.resolve_shared_resource((select b from tokens)),'{"state":"unavailable"}'::jsonb,'Deleted Activity unavailable');
select throws_ok($$select public.create_resource_share_link('activity',(select id from activity))$$,'42501',null,'Deleted Activity cannot be shared');
select public.soft_delete_project((select id from ctx));
select is(public.resolve_shared_resource((select t from sibling_token)),'{"state":"unavailable"}'::jsonb,'Deleted project makes all shares unavailable');
select * from finish();
rollback;
